const count = Number(env.get('SIM_APARTMENTS_PER_BUILDING') || 20);
const buildingId = 'building-1';
let seq = context.get('seq') || {};
const messages = [];
for (let i = 1; i <= count; i++) {
  const apartmentId = `apt-${i}`;
  const luxDevice = `lux-${buildingId}-${apartmentId}`;
  const pirDevice = `pir-${buildingId}-${apartmentId}`;
  seq[luxDevice] = (seq[luxDevice] || 0) + 1;
  seq[pirDevice] = (seq[pirDevice] || 0) + 1;
  const minute = new Date().getMinutes();
  const lux = Math.max(2, Math.round(250 * Math.max(0, 1 - minute / 60) + Math.random() * 30));
  const base = { buildingId, apartmentId, timestamp: new Date().toISOString() };
  messages.push({ payload: { ...base, eventId: RED.util.generateId(), deviceId: luxDevice, type: 'lux', sequenceNo: seq[luxDevice], lux } });
  messages.push({ payload: { ...base, eventId: RED.util.generateId(), deviceId: pirDevice, type: 'motion', sequenceNo: seq[pirDevice], motion: Math.random() > 0.38 } });
}
context.set('seq', seq);
return [messages];

if (msg.payload.type !== 'motion') return msg;
const key = msg.payload.deviceId;
const pending = context.get('pending') || {};
const last = context.get('last') || {};
if (last[key] === msg.payload.motion) return null;
if (pending[key] && pending[key].value === msg.payload.motion) return null;
if (pending[key]?.timer) clearTimeout(pending[key].timer);
const value = msg.payload.motion;
const stableMsg = RED.util.cloneMessage(msg);
const timer = setTimeout(() => { node.send(stableMsg); last[key] = value; delete pending[key]; context.set('last', last); context.set('pending', pending); }, 2500);
pending[key] = { value, timer };
context.set('pending', pending);
return null;
